scripts.clean:remotes.renovate:
bash -c '
  git fetch --prune > /dev/null;
  branches=$(git branch -r --list "origin/renovate/*" | sed "s/origin\///");
  if [[ -z "$branches" ]]; then echo "✅ No renovate branches found."; exit 0; fi;
  echo "⚠️  The following renovate branches will be deleted:"; echo "$branches" | sed "s/^/  - origin\//";
  read -p "Do you want to delete these branches? (y/N): " confirm;
  if [[ "$confirm" != "y" && "$confirm" != "Y" ]]; then echo "❌ Aborted."; exit 1; fi;
  for b in $branches; do echo "Deleting origin/$b"; git push origin --delete "$b"; done
'
